import{_ as a,H as s,f as e,i as t}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"13-JS引擎如何实现数组的稳定排序？","description":"","frontmatter":{},"headers":[{"level":2,"title":"数组的优劣势是什么","slug":"数组的优劣势是什么","link":"#数组的优劣势是什么","children":[]},{"level":2,"title":"O(n)","slug":"o-n","link":"#o-n","children":[]},{"level":2,"title":"O(1)","slug":"o-1","link":"#o-1","children":[]},{"level":2,"title":"JS 如何实现数组的排序","slug":"js-如何实现数组的排序","link":"#js-如何实现数组的排序","children":[{"level":3,"title":"理论类排序法","slug":"理论类排序法","link":"#理论类排序法","children":[]}]},{"level":2,"title":"O(n )","slug":"o-n-1","link":"#o-n-1","children":[{"level":3,"title":"常用类排序法","slug":"常用类排序法","link":"#常用类排序法","children":[]}]},{"level":2,"title":"O(n )","slug":"o-n-2","link":"#o-n-2","children":[]},{"level":2,"title":"O(nlogn)","slug":"o-nlogn","link":"#o-nlogn","children":[]},{"level":2,"title":"O(nlogn)","slug":"o-nlogn-1","link":"#o-nlogn-1","children":[]},{"level":2,"title":"排序的稳定性问题","slug":"排序的稳定性问题","link":"#排序的稳定性问题","children":[]},{"level":2,"title":"O(nlogn)","slug":"o-nlogn-2","link":"#o-nlogn-2","children":[]},{"level":2,"title":"O(n )","slug":"o-n-3","link":"#o-n-3","children":[]},{"level":2,"title":"O(n)","slug":"o-n-4","link":"#o-n-4","children":[]},{"level":2,"title":"延伸：线性类排序法","slug":"延伸-线性类排序法","link":"#延伸-线性类排序法","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"JavaScript进阶实战课/13-JS引擎如何实现数组的稳定排序？.md","filePath":"JavaScript进阶实战课/13-JS引擎如何实现数组的稳定排序？.md","lastUpdated":1795487863000}'),E={name:"JavaScript进阶实战课/13-JS引擎如何实现数组的稳定排序？.md"};function n(l,i,h,p,r,o){return s(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="_13-js引擎如何实现数组的稳定排序" tabindex="-1">13-JS引擎如何实现数组的稳定排序？ <a class="header-anchor" href="#_13-js引擎如何实现数组的稳定排序" aria-label="Permalink to &quot;13-JS引擎如何实现数组的稳定排序？&quot;">​</a></h1><p>你好，我是石川。</p><p>我们经常将数据结构和算法这两个词连起来说，可是你有没有想过，这两者是什么关系？</p><p>可以说数据结构是服务于算法的。这么说比较概括。下面我们就找一个切入点来讲解两者的关系，我们先从排序算法说起。提到排序，我们就要说到常用的数据结构数组，比如在 JS 中我们一般都用过它的排序方法，可是你知不知道排序方法背后用的是哪种算法呢？这一讲，就通过数组了解排序算法，再来看 JS 引擎是如何实现数组的排序的。</p><p>在数据结构中，我们大体可以分为两类。第一类是线性表，第二类是非线性表。这里的线性和我们生活中理解的线性没有本质上的区别，意思就是“按顺序的”。数组可以说是一种连续存储的线性表，并且可以算是一种比较基础的线性数据结构了。通过数组，我们可以实现比如之前说过的栈、队列等线性结构。你也可以用它来创建非常经典的非线性结构，比如堆和图。</p><p>除了数组以外，另外一种既基础又经典的数据结构就是对象了。对象的一个特点是含有属性，很多时候可以用来作为节点（node），通过节点相连的方式，就可以创建链式结构，比如链表；对象的另外一个特点是它支持键值对（key-value pair），通过这个特点可以用来实现散列表和字典。</p><p>回到今天的话题，我们来重点说说数组。</p><h2 id="数组的优劣势是什么" tabindex="-1">数组的优劣势是什么 <a class="header-anchor" href="#数组的优劣势是什么" aria-label="Permalink to &quot;数组的优劣势是什么&quot;">​</a></h2><p>数组作为一种线性数据结构最大的特点是连续性，带来的优势是可随机访问性，但是它的劣势是高效的插入和删除。几乎所有的语言都把数组当做一种内置的数据类型提供，在这一点上，JavaScript 也不例外。作为 JavaScript 数据类型之一，我们在前面介绍过数组。但是作为数据结构，我们可以从另一个角度来理解它。</p><p>我们前面说，数组的劣势是插入和删除，这是什么意思呢？我们假设在排队的时候，有人插</p><h2 id="o-n" tabindex="-1">O(n) <a class="header-anchor" href="#o-n" aria-label="Permalink to &quot;O(n)&quot;">​</a></h2><p>队，那么整个组的人都会往后移动。这个时候，时间复杂度为</p><ul><li>。</li></ul><p>那么使用数组的时候如何尽量克服这个劣势问题呢？和排队一样，方法就是按规矩让这个人排</p><h2 id="o-1" tabindex="-1">O(1) <a class="header-anchor" href="#o-1" aria-label="Permalink to &quot;O(1)&quot;">​</a></h2><p>到队尾。在数组中，如果把数据元素插到队尾的话，那么整个时间复杂度仅仅为</p><ul><li>。所以</li></ul><p>通常，如果我们不在乎增加一个新的数据到哪儿，那么最好就是把它加到队尾。在 JavaScript中，如何将一条信息加到数组的队尾呢？我们知道数组也是一种对象，那么它也有着一些自带的属性和方法用来对数组进行操作。在 JavaScript 当中，实现插入最简单的方式就是在数组的长度基础上算出下一个空位，赋值为我们想加入的数据元素。</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> week </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">week[week.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">length</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(week) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 返回 [1,2,3,4,5,6,7]</span></span></code></pre></div><p>在这里，你可以看到它和 C 或者 Java 相同和不同的影子。和 C 或者 Java 相同的是，我们的直觉会告诉我们开始数组长度是 6，那在第 6 个位置上赋值，怎么会是空位，这样不会覆盖到第 6 个数字吗？不会。这是因为数组通常是从 0 而不是 1 开始计算的。和 C 或者 Java 不同的是，在 JavaScript 里，数组的长度是可以动态扩容的，或者用我们之前讲的函数式思想来看，内容也是可变的，这点从上面的例子就可以看出。而在 C 和 Java 里，数组的长度是一开始就决定的，如果这时候增加一个新的数据元素，就需要创建一个新的数组。</p><p>除了上面的方法，还有另外一种方法可以快速地增加一个值到数组的尾部，这种方式就是使用JavaScript 中数组自带的 push 方法。从这里，我们大概可以看出队列和栈的影子。当我们用上面排队举例子时，其实就有队列的概念。下面的 push 在英文里，其实就是“压栈”的意思。</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> week </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">week.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">push</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(week) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 返回 [1,2,3,4,5,6,7]</span></span></code></pre></div><h2 id="js-如何实现数组的排序" tabindex="-1">JS 如何实现数组的排序 <a class="header-anchor" href="#js-如何实现数组的排序" aria-label="Permalink to &quot;JS 如何实现数组的排序&quot;">​</a></h2><p>说完了数组的优劣势，我们来看看它的排序实现。数组是如何实现排序的呢，通过下面的例子，我们可以来看看几种排序方式。其中前 2 种冒泡和选择排序是偏理论型的排序方式，后面3 种，插入、快排和归并属于应用型的算法。Chrome 用的 V8 引擎就是快排和插入排序的结合，火狐用的 SpiderMonkey 则是基于归并来实现排序的。为什么浏览器会使用这几种排序方式呢？我们可以通过它们的原理和特点来了解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/1.png" alt=""></a></p><h3 id="理论类排序法" tabindex="-1">理论类排序法 <a class="header-anchor" href="#理论类排序法" aria-label="Permalink to &quot;理论类排序法&quot;">​</a></h3><p>首先，我们先来看看理论类的冒泡、选择这两种排序算法。这两种方式用的都是一种比较和交换的方法（compare and swap）。我们上面说过，对于数组来说，如果我们在非队尾的位置插入的话，就容易造成队列中插入的元素以后的一系列元素的移动。但是如果使用交换的方式，就巧妙地避免了这个问题。</p><p>冒泡排序（bubble sort）的核心思想就是通过比较两个相邻的数据元素，如果前面的大于后面的，就交换它们的位置。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/2.png" alt=""></a></p><p>选择排序（selection sort）用的是一种原地比较的算法（in-place compare），它的核心思想就是找到最小的数据元素，把它放到第一位，然后再从剩下的数组中找到最小的数据元素，然后放到第二位，以此类推。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/3.png" alt=""></a></p><ul><li>2</li></ul><h2 id="o-n-1" tabindex="-1">O(n ) <a class="header-anchor" href="#o-n-1" aria-label="Permalink to &quot;O(n )&quot;">​</a></h2><p>之所以说这两类排序算法更多是理论层面，是因为它们的时间复杂度都是</p><ul><li>。下面我们</li></ul><p>来看看有没有时间复杂度更低的方式来处理数组的排序。</p><h3 id="常用类排序法" tabindex="-1">常用类排序法 <a class="header-anchor" href="#常用类排序法" aria-label="Permalink to &quot;常用类排序法&quot;">​</a></h3><p>下面我们再来看看一些非理论类，实际使用中常用的排序算法。</p><p>插入排序（insertion sort）和之前的冒泡和选择排序法不同，它不是用比较和交换，而是通过位移来做插入。它假设数组中第 1 个元素已经排序了。从第 2 个和第 1 个比较，如果小于第 1个值，就插入到前面，如果大于，就原地不动；第 3 个值同理和前面的 2 个比较，小于就左移插入，大于就不动；后面的操作都以此类推。虽然插入排序虽然从复杂度上来看，和冒泡及</p><ul><li>2</li></ul><h2 id="o-n-2" tabindex="-1">O(n ) <a class="header-anchor" href="#o-n-2" aria-label="Permalink to &quot;O(n )&quot;">​</a></h2><p>选择算法类似，都是</p><ul><li>，但是实际上，对于一些较短的数组来说，它的性能是明显更好</li></ul><p>的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/4.png" alt=""></a></p><h2 id="o-nlogn" tabindex="-1">O(nlogn) <a class="header-anchor" href="#o-nlogn" aria-label="Permalink to &quot;O(nlogn)&quot;">​</a></h2><p>归并排序（merge sort）可以算是比较常见的应用型排序算法了，它的复杂度是</p><ul><li>。</li></ul><p>下面，我们就来看看它的实现。归并算法用到的是我们前面介绍过的递归和分治的算法思想。这种方法的核心就是先把一个大的数组拆分成只包含一个元素的不可再分的数组，然后两两比较，最后再合并成一个数组。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/5.png" alt=""></a></p><p>下面，我们再来看看快排算法（quick sort），和归并类似，快排也用到了递归和分治，同样，</p><h2 id="o-nlogn-1" tabindex="-1">O(nlogn) <a class="header-anchor" href="#o-nlogn-1" aria-label="Permalink to &quot;O(nlogn)&quot;">​</a></h2><p>它的时间复杂度是</p><ul><li>。说它也用了分治，是因为快排也会对数组“分开来”分析；但是</li></ul><p>和归并不同的是，它不会把元素真的“拆出来”再组合。那么它是怎么实现排序的呢？</p><p>在快排中，用到的是区分点（pivot）和指针（pointer）。在数组中，我们会在最前和最后一个元素的位置各加一个指针，然后在中间的位置加一个区分点。我们会不断移动左指针，直到我们找到一个元素大于区分点；同时，我们也会不断移动右指针，直到我们找到一个小于区分点的数，然后将它和左指针指向的数据交换。这里类似我们在冒泡排序中提到的比较和交换的算法。这个过程可以使得所有区分点左边的值都小于右边的数，这个过程叫做分区（partition）。这个方式会按照递归的方式不断重复，直到最后整个数组排序完成。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/JavaScript%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/13-JS%25E5%25BC%2595%25E6%2593%258E%25E5%25A6%2582%25E4%25BD%2595%25E5%25AE%259E%25E7%258E%25B0%25E6%2595%25B0%25E7%25BB%2584%25E7%259A%2584%25E7%25A8%25B3%25E5%25AE%259A%25E6%258E%2592%25E5%25BA%258F%25EF%25BC%259F/6.png" alt=""></a></p><p>关于快排有一点需要注意，就是分区的实现。关于分区实现中的区分点，我们需要注意的是为了避免分区后两个区域的数据量相差很大，我们可以默认在两个指针之间选一个平均值，但更好的办法是通过随机的方式来选择，虽然这样不能保证最好的结果，但从概率角度，也不会太差。</p><h2 id="排序的稳定性问题" tabindex="-1">排序的稳定性问题 <a class="header-anchor" href="#排序的稳定性问题" aria-label="Permalink to &quot;排序的稳定性问题&quot;">​</a></h2><p>前面我们说了那么多，那么回到我们之前的问题，为什么 V8 用的是插入加快排的方式，SpiderMonkey 用的是归并的方式来做排序呢？这就要从排序的稳定性说起了。在ECAMScript 的官方文档中，虽然并不指定 JS 引擎对 sort 的具体实现方式，但是有一条准则，就是要确保数组的排序必须是稳定排序（stable sort）。</p><p>从理论上讲，虽然归并和快排的复杂度都是相同的，但是前面我们忽略了两个重要因素，第一个是时间复杂度的平均和极端情况，第二个是空间复杂度的问题。快排在平均情况下的空间复</p><ul><li>2</li></ul><h2 id="o-nlogn-2" tabindex="-1">O(nlogn) <a class="header-anchor" href="#o-nlogn-2" aria-label="Permalink to &quot;O(nlogn)&quot;">​</a></h2><h2 id="o-n-3" tabindex="-1">O(n ) <a class="header-anchor" href="#o-n-3" aria-label="Permalink to &quot;O(n )&quot;">​</a></h2><p>杂度是</p><ul><li>，但是在极端情况下是。</li></ul><p>那你会说，这样为什么不直接用归并排序，因为归并排序也不是没有问题，在使用归并排序的</p><h2 id="o-n-4" tabindex="-1">O(n) <a class="header-anchor" href="#o-n-4" aria-label="Permalink to &quot;O(n)&quot;">​</a></h2><p>时候，虽然它是稳定的，但它不是原地排序法，这就造成了它的空间复杂度是</p><ul><li>，必然要</li></ul><p>高于其它的算法类型。所以这就是为什么 V8 和 SpiderMonkey 各自选择不同算法的原因。对于 V8 而言，为了既解决稳定性问题，又解决复杂度问题，就使用了快排加插入的方式，在数据量比较小的情况下，使用插入；在数据量比较大的时候，则切换到快排。而对于SpiderMonkey 来说，就通过归并来满足稳定性的需求。</p><h2 id="延伸-线性类排序法" tabindex="-1">延伸：线性类排序法 <a class="header-anchor" href="#延伸-线性类排序法" aria-label="Permalink to &quot;延伸：线性类排序法&quot;">​</a></h2><p>还有一类的排序法我们称之为线性排序法，为什么这么叫呢。因为他们使用的都是非比较类的排序方法，这里包括了计数、桶和基数排序，因为这几种排序算法都是用于特殊场景，我们就不在这里讲它们的具体实现了，但是我也会把源码放到 GitHub 上。如果你想做延伸了解，可以通过代码注释来了解。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我们通过数组这种最简单的数据结构了解了并不简单的排序算法。你应该学到了数组这种数据结构的优劣性，同时我们也看到了 V8 和 SpiderMoney 使用的排序方式。这一讲最核心的并不是我们学到了这些逻辑和应用，更重要的是我们看到了全面分析的思维方式。比如我们看到的时间复杂度只是一个方面，它不能直接代替性能。当我们把它和稳定性及空间复杂度的思考维度相加的时候，才能对解决方案作出更全面和客观的判断。同时，这也告诉我们我们所写的程序基于不同的引擎和数据量可能会有不同的结果。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>今天留给你的思考题是，通过今天学到的知识，你能不能讲讲你知道的其它的 JS 引擎用的是什么算法？</p><p>期待在留言区看到你的分享，我们一起交流讨论。另外，也欢迎你把今天的内容分享给更多的朋友。我们下期再见！</p>`,78)])])}const g=a(E,[["render",n]]);export{B as __pageData,g as default};
